// subscribe to a server-sent event feed
function subscribe(url, onItem) {
  const es = new EventSource(url);

  es.onmessage = (e) => {
    onItem(JSON.parse(e.data));
  };

  es.onerror = () => {
    es.close();
    setTimeout(() => subscribe(url, onItem), 1000);
  };

  return es;
}
